    nefertari: {"title": "الملكة نفرتاري تلعب السنت", "artist": "نينا دي غاريس ديفيز (نسخة)", "date": "الأصل نحو 1290–1224 ق.م · النسخة 1921–22", "place": "مصر (وادي الملكات)", "game": "السنت", "medium": "تمبرا على ورق (نسخة بنصف الحجم)", "p": ["كانت نفرتاري الزوجة الملكية الكبرى لرمسيس الثاني. هذه نسخة من رسم في مقبرتها بوادي الملكات، صُنعت داخل المقبرة نفسها في 1921–22، ونُقلت حتى الشقوق والأجزاء المفقودة من الجدار.", "تجلس الملكة أمام رقعة وتلعب السنت مع خصم غير مرئي. ويُرجَّح أن اللعبة المرسومة في مقبرة كانت تعني أكثر من التسلية: الفوز في رحلة العالم الآخر."], "spots": [["نوعان من القطع", "على الرقعة قطع مدبّبة الرأس وقطع على شكل بكرة: مجموعة لكل لاعب."], ["يد الملكة", "أصابعها تمتد إلى قطعة."], ["الرقعة والحامل", "رُسمت الرقعة من الجانب فلا تظهر خاناتها، وهي على حامل رفيع الأرجل."], ["اسمها", "اسم الملكة مكتوب داخل إطار بيضاوي يسمّى الخرطوش."], ["الخصم الخفي", "لا أحد أمامها: إنها تلعب مع خصم لا يُرى."]]},
    hydria: {"title": "أخيل وأياكس يلعبان لعبة رقعة (جرّة ماء)", "artist": "يُنسب إلى مجموعة لياغروس", "date": "نحو 510 ق.م", "place": "اليونان (أتيكا)", "game": "لعبة نرد", "medium": "فخار (أسلوب الأشكال السوداء)", "p": ["في أثناء حصار طروادة يقضي بطلان يونانيان، أخيل وأياكس، الوقت حول رقعة. ابتكر هذا المشهد نحو 540 ق.م الخزّاف والرسام إكسيكياس، وأصله محفوظ على أمفورا في متاحف الفاتيكان.", "لقي الموضوع رواجًا كبيرًا بين نحو 540 و480 ق.م، ويُعرف منه أكثر من 150 مثالًا. وفي هذه الجرّة تقف الإلهة أثينا في الوسط. يلعب البطلان لعبة تتحرك فيها القطع بحسب رمية النرد."], "spots": [["أثينا", "تقف الإلهة أثينا بين الاثنين."], ["البطل الأيسر", "ما زال الرمح في يده وهو ينحني على الرقعة."], ["البطل الأيمن", "لم يضع سلاحه هو الآخر: لحظة لعب في قلب الحرب."], ["الرقعة", "الكتلة المنخفضة بينهما هي الرقعة."], ["الكتف", "على كتف الجرّة عربة تنطلق."]]},
    liubo: {"title": "تمثالان جالسان يلعبان ليوبو", "date": "القرن الأول ق.م – القرن الأول م", "place": "الصين (أسرة هان)", "game": "ليوبو", "medium": "فخار ملوّن", "p": ["لاعبان لليوبو، اللعبة التي شغفت بها صين أسرة هان. كانت مثل هذه التماثيل توضع في القبور أملًا في أن تستمر متع الحياة بعد الموت.", "في الصورة وُضعت بينهما رقعة ليوبو وقطع العظم من مقتنيات هذا المتحف. ويلتقط التمثالان لحظة مثيرة من مباراة حامية."], "spots": [["رقعة ليوبو", "هي نفسها «رقعة ليوبو وقطعها» في المقتنيات: لاحظ علامات T وL وV."], ["اللاعب الأيسر", "يتأمل الرقعة بهدوء."], ["اللاعب الأيمن", "يده مرفوعة وفمه مفتوح: هل قام للتوّ بالحركة الحاسمة؟"], ["قطع على الرقعة", "قطع العظم قائمة عند طرفي الرقعة."], ["قطع خارج الرقعة", "وهناك قطع أخرى على الأرض."]]},
    shahnama: {"title": "«بزرجمهر يحلّ لغز لعبة الشطرنج الهندية»، من شاهنامه الشاه طهماسب", "artist": "يُنسب الرسم إلى عبد الوهاب", "date": "نحو 1530–35", "place": "إيران (تبريز)", "game": "الشطرنج", "medium": "ألوان مائية معتمة وحبر وفضة وذهب على ورق", "p": ["مشهد من ملحمة الفردوسي «الشاهنامه» (كتاب الملوك). يرسل ملك الهند رسولًا معه رقعة شطرنج وقطعها، ويتحدى ملك الفرس أنوشروان: إن عرف كيف تُلعب دفعت الهند الجزية.", "لم يحلّها في الوقت المحدد إلا الحكيم الشاب بزرجمهر. وفي الشاهنامه ترسل فارس النرد في المقابل، فيعجز الهنود عن حلّه. يحدّق الملك وحاشيته في الرقعة واللاعبين."], "spots": [["رقعة الشطرنج", "القطع على رقعة مربعات، صغيرة جدًا حتى يصعب تمييز أشكالها."], ["الملك أنوشروان", "على عرشه ينتظر حلّ اللغز."], ["حول الرقعة", "اللاعبون منحنون على الرقعة."], ["الأبيات", "في الإطارين العلوي والسفلي أبيات من الفردوسي."], ["الحاشية", "رجال بعمائم ذات عصيّ حمراء طويلة يتفرجون وقوفًا."]]},
